; The deck of the Gull's Wager at night, two days out from Questeria: the Prologue's voyage. Its
; boards inside the bulwark, the hatch over the hold, the mainmast amidships with the crow's nest
; at the top, lanterns at the rail, and the wheel at the stern. Dark, with the lanterns lighting it.
; There's no way off but the end of the Prologue.

[map]
id = gulls-wager
name = The Gull's Wager
tileset = ship
size = 40 24
dark = yes
ambient = 0.35
fog = no
music = Title

[legend]
- = deck
# = bulwark
= = hatch
~ = sea

